for t in range(0, int(input())):
	(n, k) = map(int, input().split())
	arr = list(map(int, input().split()))[:n]
	N = 1024
	dp = [0] * 1024
	dp[0] = 1
	for i in range(0, n):
		for j in range(0, N):
			if dp[j] == 1:
				value = j ^ arr[i]
				dp[value] = 1
	ans = 0
	for i in range(0, N):
		if dp[i] == 1:
			ans = max(ans, i ^ k)
	print(ans)
